// ===========================================================================
// phase hook — ONE entry point for Claude Code and Codex lifecycle hooks
// ===========================================================================
//
// Both tools send the event as JSON on stdin with `hook_event_name`, `cwd`, and
// for tool events `tool_name` + `tool_input`. Codex edits files through
// `apply_patch` (patch text); Claude Code through Write/Edit/MultiEdit.
// Contract: exit 2 + stderr blocks a PreToolUse; stdout JSON carries context.

export const STEP_NAMES = {
  discover: 'Step 1 of 4 — describe the app',
  mock: 'Step 2 of 4 — preview the design',
  build: 'Step 3 of 4 — build it for real',
  ship: 'Step 4 of 4 — go live',
};

export const PLAIN_LANGUAGE =
  'Talk to the user as a friendly product manager would talk to a business owner: plain words, short answers, one question at a time. ' +
  'Never show them internal words such as phase, gate, hook, SPEC, R-001/S-001 ids, npx, CLI commands, JSON, or file paths unless they ask. ' +
  'Describe progress as the four steps: describe the app, preview the design, build it for real, go live. ' +
  'When something is blocked, fix it yourself and tell them in one plain sentence what you changed and why.';

export function readRuleFile(rulesDir, topic) {
  if (!rulesDir) return '';
  try {
    return readFileSync(join(rulesDir, `${topic}.md`), 'utf-8').trim();
  } catch {
    return '';
  }
}

export function hookContext(event, text) {
  return JSON.stringify({ hookSpecificOutput: { hookEventName: event, additionalContext: text } });
}

export function isApprovalPrompt(prompt) {
  const p = String(prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
  return p === 'approve' || p === 'approved' || p === 'i approve' || p === '/piezas:approve' || p === '/approve';
}

// patchTextFrom — the patch text an apply_patch call carries, read only from
// the tool's own input fields (input / patch / command, a string or an argv
// array). Never from file content: a Write whose content merely contains
// "*** Begin Patch" is a Write to its file_path.
export function patchTextFrom(input) {
  if (typeof input === 'string') return input.includes('*** Begin Patch') ? input : null;
  if (Array.isArray(input)) {
    for (const part of input) if (typeof part === 'string' && part.includes('*** Begin Patch')) return part;
    return null;
  }
  if (input && typeof input === 'object') {
    for (const field of ['input', 'patch', 'command', 'cmd']) {
      const found = patchTextFrom(input[field]);
      if (found) return found;
    }
  }
  return null;
}

// parsePatch — Codex's apply_patch envelope -> [{ path, op, added,
// lines, from }]. A moved file appears twice: its old place (op 'move-from',
// a delete) and its new one (op 'move', with `from`). `lines` are the change's
// own lines, for applyPatchLines.
export function parsePatch(text) {
  const files = [];
  let current = null;
  for (const line of String(text).split('\n')) {
    const header = /^\*\*\* (Add|Update|Delete) File: (.+)$/.exec(line);
    const move = /^\*\*\* Move to: (.+)$/.exec(line);
    if (header) {
      current = { path: header[2].trim(), op: header[1].toLowerCase(), added: [], lines: [] };
      files.push(current);
    } else if (move && current) {
      const from = current;
      from.op = 'move-from';
      current = { path: move[1].trim(), op: 'move', added: from.added, lines: from.lines, from: from.path };
      files.push(current);
    } else if (current && line.startsWith('***')) {
      if (/^\*\*\* End Patch/.test(line)) current = null;
    } else if (current) {
      current.lines.push(line);
      if (line.startsWith('+')) current.added.push(line.slice(1));
    }
  }
  return files.map((f) => ({
    path: f.path, op: f.op, added: f.added.join('\n'), lines: f.lines, ...(f.from ? { from: f.from } : {}),
  }));
}

// applyPatchLines — a file's text after an apply_patch update (hunks of
// " context", "-removed", "+added" lines, split by "@@"), or null when a hunk
// does not match the file.
export function applyPatchLines(text, lines) {
  let out = String(text ?? '');
  let cursor = 0;
  const hunks = [];
  let hunk = [];
  for (const line of lines) {
    if (line.startsWith('@@')) { if (hunk.length) hunks.push(hunk); hunk = []; continue; }
    hunk.push(line);
  }
  if (hunk.length) hunks.push(hunk);
  for (const h of hunks) {
    const body = h.filter((l, i) => !(l === '' && i === h.length - 1));
    const oldLines = body.filter((l) => !l.startsWith('+')).map((l) => (l.startsWith('-') || l.startsWith(' ') ? l.slice(1) : l));
    const newLines = body.filter((l) => !l.startsWith('-')).map((l) => (l.startsWith('+') || l.startsWith(' ') ? l.slice(1) : l));
    if (!oldLines.length) {
      out = `${out}${out && !out.endsWith('\n') ? '\n' : ''}${newLines.join('\n')}\n`;
      continue;
    }
    const oldText = oldLines.join('\n');
    const at = out.indexOf(oldText, cursor);
    if (at < 0) return null;
    out = out.slice(0, at) + newLines.join('\n') + out.slice(at + oldText.length);
    cursor = at + newLines.join('\n').length;
  }
  return out;
}

function readFileOr(path, fallback) {
  try { return readFileSync(path, 'utf-8'); } catch { return fallback; }
}

// proposedText — the whole file an edit-tool call would leave, or null when it
// cannot be worked out (the guard then treats a protected file as unchecked).
export function proposedText(tool, input, abs) {
  if (tool === 'Write') return typeof input.content === 'string' ? input.content : null;
  const current = readFileOr(abs, null);
  if (current === null) return null;
  const applyOne = (text, e) => {
    if (text === null || !e || typeof e.old_string !== 'string' || typeof e.new_string !== 'string') return null;
    if (!text.includes(e.old_string)) return null;
    return e.replace_all ? text.split(e.old_string).join(e.new_string) : text.replace(e.old_string, () => e.new_string);
  };
  if (tool === 'Edit') return applyOne(current, input);
  if (tool === 'MultiEdit') {
    if (!Array.isArray(input.edits)) return null;
    return input.edits.reduce((text, e) => applyOne(text, e), current);
  }
  return null;
}

export function shellCommandFrom(input) {
  const cmd = input?.command ?? input?.cmd;
  // Codex's shell tool sends ["bash", "-lc", "<script>"]: the script is the command.
  if (Array.isArray(cmd) && cmd.length >= 3 && /(?:^|\/)(?:ba|z|da)?sh$/.test(String(cmd[0])) && /^-[a-z]*c$/.test(String(cmd[1]))) {
    return cmd.slice(2).join(' ');
  }
  if (Array.isArray(cmd)) return cmd.join(' ');
  return typeof cmd === 'string' ? cmd : '';
}

export function preToolUse(payload, cwd, env = process.env) {
  const tool = typeof payload.tool_name === 'string' ? payload.tool_name : '';
  const input = payload.tool_input ?? {};
  // The host's session id scopes the owner's "allow outside changes" to one session.
  const sessionId = typeof payload.session_id === 'string' && payload.session_id ? payload.session_id : undefined;
  const workdir = typeof input.workdir === 'string' && input.workdir ? input.workdir : undefined;

  // Codex's apply_patch (some hosts report it as Edit/Write with no file path):
  // the files are the patch's own headers. An Edit/Write with a file_path is
  // judged by that path, whatever its content says.
  const ownPath = typeof input.file_path === 'string' || typeof input.path === 'string' || typeof input.notebook_path === 'string';
  const patch = tool === 'apply_patch' || ((tool === 'Edit' || tool === 'Write') && !ownPath) ? patchTextFrom(input) : null;
  if (patch) {
    const base = workdir ? resolve(cwd, workdir) : cwd;
    for (const file of parsePatch(patch)) {
      const abs = resolve(base, file.path);
      // The whole file this leaves: an added file as written, an update (or a
      // move's new place) as the old text with the change applied.
      const source = file.op === 'move' ? resolve(base, file.from) : abs;
      const proposed = file.op === 'add' ? file.added + (file.added ? '\n' : '')
        : file.op === 'update' || file.op === 'move' ? applyPatchLines(readFileOr(source, ''), file.lines) : null;
      const verdict = phaseGuard({
        cwd, tool: 'Write', file: abs, content: file.added,
        deleting: file.op === 'delete' || file.op === 'move-from', proposed, sessionId, env,
      });
      if (verdict.exitCode === 2) return verdict;
    }
    return guardAllow();
  }

  if (tool === 'Bash' || tool === 'shell' || tool === 'exec_command') {
    return phaseGuard({ cwd, workdir, tool: 'Bash', command: shellCommandFrom(input), sessionId, env });
  }

  if (tool === 'NotebookEdit') {
    return phaseGuard({ cwd, tool: 'Write', file: input.notebook_path, content: typeof input.new_source === 'string' ? input.new_source : undefined, sessionId, env });
  }

  if (tool === 'Write' || tool === 'Edit' || tool === 'MultiEdit') {
    const content =
      typeof input.content === 'string'
        ? input.content
        : typeof input.new_string === 'string'
          ? input.new_string
          : Array.isArray(input.edits)
            ? input.edits.map((e) => (e && typeof e.new_string === 'string' ? e.new_string : '')).join('\n')
            : undefined;
    // The settings checks judge the whole file the edit leaves (proposed).
    const target = input.file_path ?? input.path;
    const proposed = typeof target === 'string' ? proposedText(tool, input, resolve(cwd, target)) : null;
    return phaseGuard({ cwd, tool, file: target, content, proposed, sessionId, env });
  }
  return guardAllow();
}

// ownerDeployReplies — the owner's own typed reply to a waiting deploy pause,
// recorded under root: notes for the AI ([] when the message is none).
// Options: via (the record's 'via' for the pause answer: 'user-prompt', or
// 'relayed' for --owner-reply), checkChange (false: the rewritten-check OK is
// not read here; with no hooks it goes through test --accept-change).
export function ownerDeployReplies(root, prompt, options = {}) {
  const via = options.via ?? 'user-prompt';
  const notes = [];
  const said = String(prompt || '').trim().toLowerCase().replace(/[.!]+$/, '');
  if (said === DEPLOY_ANYWAY || said === '/piezas:deploy-anyway') {
    const shown = pendingDeployRisk(root);
    if (shown?.fingerprint && !shown.silent) {
      // The answer is about the pause the owner read, never a newer one.
      const { changedSince } = recordPauseAnswer(root, shown, via, prompt);
      markPauseAnswered(root);
      if (changedSince) {
        notes.push('The owner typed "deploy anyway" for the pause they were shown, but the code has changed since: it is recorded for that earlier version only. Run the deploy again and pass on what it prints; do not tell them this version is going live.');
      } else {
        notes.push(`The owner confirmed (${via === 'relayed' ? 'relayed: "deploy anyway"' : 'they typed "deploy anyway"'}) putting this version live despite the problems found. Run the deploy again now; tell them in one sentence that it is going live and that fixing the problem is still recommended.`);
        const quality = qualityGateVerdict(root);
        if (quality.applies && !quality.ok) notes.push('The quality scan is not done for this version either: for that, the owner\'s own phrase is "go live without the scan" (only they can say it).');
      }
    } else {
      // Nothing shown to the owner: the AI is still on its work (the quality
      // scan, the checks). Their own "deploy anyway" still counts (the
      // override never goes away): for the scan it is the one-time skip for
      // this version; for the checks it is recorded against the gate as it is
      // now, and its items (marked unseen: never "the same as last time").
      // Something else may still pause the next deploy, so the AI is not told
      // it goes live.
      const quality = qualityGateVerdict(root);
      const skipped = quality.applies && !quality.ok && recordQualitySkip(root, prompt, via === 'relayed' ? 'relayed' : 'owner-reply', { verdict: quality });
      const working = aiWorkPause(root);
      if (working) recordPauseAnswer(root, working, via, prompt, { unseen: true });
      if (skipped || working) {
        const what = [skipped ? 'without the quality scan' : '', working ? 'without finishing the checks' : ''].filter(Boolean).join(' and ');
        notes.push(`The owner typed "deploy anyway" while you were still working: going live ${what} is recorded for this version as it is now. Stop fixing; run the deploy again now and pass on what it prints. Do not say it is going live until the deploy says so.`);
      } else {
        notes.push('The owner typed "deploy anyway", but no deploy is waiting for confirmation. Tell them where things stand in one sentence.');
      }
    }
  }
  const testGateReply = said === DEPLOY_ANYWAY ? '' : recordTestGateReply(root, prompt, via === 'relayed' ? 'relayed' : 'owner-reply');
  if (testGateReply) notes.push(testGateReply);
  const checkChangeReply = options.checkChange === false ? '' : recordCheckChangeReply(root, prompt);
  if (checkChangeReply) notes.push(checkChangeReply);
  // "link to <app name>": the owner's own word to replace a live version
  // this project did not put there.
  const linkReply = recordAppLinkReply(root, prompt, via === 'relayed' ? 'relayed' : 'user-prompt');
  if (linkReply) notes.push(linkReply);
  return notes;
}

// relayDeployReply — `piezas deploy --owner-reply "<their words>"`. With no
// hooks in this session to record the owner's reply in the chat (the Claude
// connector, the Codex plugin, a project set up through the MCP, a session not
// trusted yet), the AI relays their exact words: an answer to the pause the
// deploy printed ("deploy anyway", "keep trying", "check again", "skip <part>",
// "go live without the scan") or to its link question ("link to <app>"),
// recorded as relayed. Anything else is refused and records nothing. With the
// hooks running it is refused (the guard refuses the command, too).
// Returns { ok, notes, goLive } or { ok: false, error }; goLive says whether
// the deploy should run now (an answer that lets it go on).
// The owner's "fix it first" to a pause.
const FIX_FIRST = /^(?:please |ok,? |okay,? )?(?:keep (?:fixing|working|trying)|fix (?:it|this|that|them|those|these)(?: first| please)?|(?:please )?fix(?: it)?|try again|have (?:it|the ai|my ai) fix (?:it|this|that))\b/;

export function relayDeployReply(projectDir, words) {
  const root = deployRecordRoot(projectDir);
  const said = String(words ?? '').trim();
  const lower = said.toLowerCase().replace(/[.!]+$/, '').trim();
  if (!said) return { ok: false, error: '--owner-reply needs the owner\'s exact words.' };
  if (!relayAllowed(root)) {
    return { ok: false, error: 'The Piezas hooks are installed or running for this project, so they record the owner\'s own reply in the chat. Run the deploy again without --owner-reply after they answer.' };
  }
  if (HANDS_BACK.test(lower)) {
    return { ok: false, error: `"${said.slice(0, 120)}" is not a choice. Give your recommendation in one sentence and ask the owner again.` };
  }
  const again = 'Run npx piezas deploy (without --owner-reply), show the owner exactly what it prints, and relay their answer to that.';
  // The link question has its own record.
  if (/^(?:please )?link\b/.test(lower)) {
    const note = recordAppLinkReply(root, said, 'relayed');
    return /it is recorded/.test(note) ? { ok: true, notes: [note], goLive: true } : { ok: false, error: `${note} ${again}` };
  }
  // No Stop hook saw the AI relay a newer pause: the owner may not have read it.
  if (promoteQueuedPause(root)) {
    return { ok: false, error: `The deploy printed a newer pause than the one the owner answered. ${again}` };
  }
  const anyway = exactDeployAnyway(said);
  const skipScan = !anyway && Boolean(readSkipPhrase(said));
  // "yes <part>" OKs a rewritten check: that has its own command.
  const pendingChecks = readCheckChange(root)?.scenarios ?? [];
  const okChecks = pendingChecks.length && !anyway && !skipScan ? approvedCheckChanges(said, pendingChecks, pendingChecks) : [];
  if (okChecks.length) {
    return {
      ok: false,
      error: `These words OK a rewritten check. Run: ${okChecks.map((c) => `npx piezas test --accept-change ${c.id} --reason "<what changed and why>" --owner-reply "${said.replace(/"/g, "'")}"`).join(' && ')}, then npx piezas test, then deploy.`,
    };
  }
  const shown = pendingDeployRisk(root);
  if (shown?.needsShow) return { ok: false, error: `The owner has not been shown the deploy's newest pause yet. ${again}` };
  if (!shown?.fingerprint || shown.silent) {
    // Nothing asked of the owner yet: still the AI's own work (the checks'
    // rounds, the quality scan); the deploy asks them after its tries.
    const scan = skipScan ? ' For the quality scan alone, their words can go to: npx piezas quality-scan skip --owner-reply "<their words>".' : '';
    return { ok: false, error: `The deploy has not asked the owner anything yet: this is still your own work (the checks or the quality scan). Carry on as the deploy said, then run it again; it asks them after your tries.${scan}` };
  }
  const items = Array.isArray(shown.items) ? shown.items : [];
  // The checks' words ("keep trying", "skip <part>") only answer a pause about the checks.
  const gate = anyway || skipScan || shown.kind !== 'test-gate' ? null : readGateReply(said, items);
  // "fix it first": no record; the AI fixes what the pause names, then deploys.
  if (!anyway && !skipScan && !gate && FIX_FIRST.test(lower)) {
    return { ok: true, notes: ['The owner wants this fixed first (relayed). Fix what the pause names, then run the deploy again. Nothing was recorded.'], goLive: false };
  }
  if (!anyway && !skipScan && !gate) {
    return { ok: false, error: `The owner's words ("${said.slice(0, 120)}") are not one of the pause's answers, so nothing was recorded. Show them its choices again and relay exactly what they answer.` };
  }
  let notes;
  if (skipScan) {
    const quality = qualityGateVerdict(root);
    if (!quality.applies || quality.ok) return { ok: false, error: 'The quality scan is not what this pause is waiting for. Show the owner the pause\'s choices again and relay their answer.' };
    recordQualitySkip(root, said, 'relayed', { verdict: quality });
    notes = ['Going live without the quality scan is recorded for this version as it is now (relayed). Run the deploy again; something else may still pause it.'];
  } else {
    notes = ownerDeployReplies(root, said, { via: 'relayed', checkChange: false });
  }
  if (!notes.length) return { ok: false, error: `Nothing was recorded for "${said.slice(0, 120)}". ${again}` };
  const goLive = anyway || skipScan || gate?.choice === 'deploy' || gate?.choice === 'skip';
  return { ok: true, notes, goLive };
}

export const OFFLINE_FETCH = () => Promise.reject(new Error('offline'));
// Doctor codes for the Hard No rules: secret exposure (PZ001/PZ002), provider
// token storage (PZ004-PZ006), local database (PZ020), public-prefixed secret (PZ021).
export const HARD_NO_CODES = new Set(['PZ001', 'PZ002', 'PZ004', 'PZ005', 'PZ006', 'PZ020', 'PZ021']);

// What the owner sees when a session starts in a Piezas project with the checks on.
export const GUARDRAILS_ON = 'Piezas guardrails are on.';

// What a PreToolUse refusal says when the check itself could not run.
export const HOOK_FAILED_REASON = 'Piezas check could not run; refusing this step. (For the AI: run `npx piezas doctor` to see why.)';

// manifestRootOf — the nearest folder at or above cwd with a
// piezas.manifest.json, or null.
function manifestRootOf(cwd) {
  let d = resolve(cwd);
  for (;;) {
    if (existsSync(join(d, 'piezas.manifest.json'))) return d;
    const parent = dirname(d);
    if (parent === d) return null;
    d = parent;
  }
}

export async function phaseHook(payload, options = {}) {
  const done = (exitCode = 0, stdout = '', stderr = '') => ({ exitCode, stdout, stderr });
  if (!payload || typeof payload !== 'object') return done();
  const event = payload.hook_event_name;

  try {
    const cwd = typeof payload.cwd === 'string' && payload.cwd ? payload.cwd : process.cwd();
    const session = sessionRoot(cwd);
    const root = session.root;
    // Every Piezas app, guided or not: the marker says the hooks run here.
    // Only in an app's own folder (its manifest): never in a folder that is
    // not one, where a .piezas folder would make it look like an app.
    // On a tool call only once its .piezas folder exists: a tool call must see
    // the folder as it was, never one the hook just created.
    const appRoot = root ? null : manifestRootOf(cwd);
    const markerRoot = root ?? (event !== 'PreToolUse' || (appRoot && existsSync(join(appRoot, '.piezas'))) ? appRoot : null);
    if (markerRoot && event) writeGuardMarker(markerRoot, payload);

    if (event === 'PreToolUse') {
      const verdict = preToolUse(payload, cwd, options.env ?? process.env);
      if (verdict.exitCode !== 2) return done();
      // Structured deny: both Claude Code and Codex read it, show it as a clean
      // "blocked" notice, and hand the reason to the model as a work order.
      return done(
        0,
        JSON.stringify({
          hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: verdict.reason || HOOK_FAILED_REASON },
        }),
      );
    }

    if (event === 'SessionStart') {
      const signInLine = signInContext(options.env ?? process.env, options.cliPath);
      const cliLine = options.cliPath
        ? `Piezas command (run it with the shell tool): node "${options.cliPath}" <args> — e.g. node "${options.cliPath}" phase status --context. ` +
          `Wherever a Piezas message says \`npx piezas ...\`, run node "${options.cliPath}" ... instead.`
        : '';
      if (!root) {
        const several = (session.several ?? []).map((d) => `${toPosix(relative(resolve(cwd), d))}/`);
        return done(
          0,
          hookContext(
            'SessionStart',
            ['The Piezas plugin is installed. If the user wants to build a business app (bookings, CRM, intake, projects, a client portal), use the piezas skill to guide them.',
              several.length ? `Piezas projects below this folder: ${several.join(', ')}. Ask which one they mean, then work inside it.` : '',
              signInLine, cliLine]
              .filter(Boolean)
              .join('\n'),
          ),
        );
      }
      const state = loadState(root);
      const gaps = gateGaps(root, state);
      const sandbox = isSandboxProject(root);
      const manifest = sandbox ? readManifestSafe(root) : null;
      const appUrl = manifest?.deploy?.url || (manifest?.appName ? `https://${slugifyAppName(manifest.appName)}.${new URL(DEFAULT_APPS_URL).host}` : '');
      const parts = [
        `[Piezas] This project is a Piezas app. ${STEP_NAMES[state.phase]}.`,
        session.below
          ? `The project is in the folder ${toPosix(relative(resolve(cwd), root))}/ below this session's folder: work there, and run every Piezas command from inside it.`
          : '',
        PLAIN_LANGUAGE,
        sandbox
          ? `${SANDBOX_NOTE} Use the normal Piezas commands (init, deploy, env, status); they run against the simulator. ` +
            `The app's address will be ${appUrl} (simulated). The running app's own data calls cannot reach real Piezas until it is connected, so test screens with sample data.`
          : signInLine,
        cliLine,
        readRuleFile(options.rulesDir, 'core'),
        options.rulesDir
          ? `Before writing code against a Piezas service, read its rules file in ${options.rulesDir}: entities.md, users.md, integrations.md, calendar.md, documents.md, deploy.md, testing.md, patterns.md.`
          : '',
        importNote(root, state.phase),
        qualityContextNote(root, state.phase),
        'Project state (for you, not for the user):',
        ...contextLines(state, gaps),
      ];
      const context = hookContext('SessionStart', parts.filter(Boolean).join('\n\n'));
      // The hook entries (hookentry.js) ask for a one-line confirmation the
      // owner sees: the checks are running in this project.
      if (!options.confirm) return done(0, context);
      return done(0, JSON.stringify({ systemMessage: GUARDRAILS_ON, ...JSON.parse(context) }));
    }

    if (event === 'UserPromptSubmit') {
      // A secret typed into the chat is held back before the AI sees it, with a
      // plain warning: chat history can be kept for a long time. The owner can
      // still send it, by starting the message with "send anyway". Runs in
      // every folder.
      const secret = secretInPrompt(payload.prompt);
      const sendAnyway = isSendAnyway(payload.prompt);
      if (secret && !sendAnyway) {
        return done(0, JSON.stringify({ decision: 'block', reason: secretBlockReason(secret) }));
      }
      const secretNote = secret ? secretSentNote(secret) : '';
      // The owner's own "allow outside changes" (any Piezas project, with or
      // without the delivery protocol): recorded here, from their message only.
      // The owner's replies to a deploy pause ("deploy anyway", a test-stop
      // answer, OK to a changed check) hold in any Piezas app, with or without
      // the delivery protocol's state file.
      const replyRoot = root ?? ownerReplyRoot(cwd);
      // Recording the owner's replies, once per message: with the plugin and
      // the project hooks both running, the second entry gets the first one's
      // notes instead of recording again (and saying "nothing was recorded").
      const record = () => {
        const out = { notes: [], quality: false };
        out.notes.push(recordOutsideOverride(replyRoot, payload));
        if (replyRoot) out.notes.push(...ownerDeployReplies(replyRoot, payload.prompt));
        // The owner's quality scan replies ("quality scan on/off", their answer
        // to the consent question, "accept 2"), from their message only.
        const qualityNote = replyRoot && !secret ? recordQualityReply(replyRoot, payload.prompt) : '';
        if (qualityNote) { out.notes.push(qualityNote); out.quality = true; }
        if (root) {
          out.notes.push(recordOwnerReply(root, payload.prompt));
          if (isApprovalPrompt(payload.prompt)) {
            const now = loadState(root);
            if (now.phase === 'mock') {
              if (!approvalFor(now, 'mock')) {
                const approval = { gate: 'mock', by: 'user', via: 'user-prompt', at: new Date().toISOString() };
                saveState(root, { ...now, approvals: [...now.approvals, approval] });
              }
              out.notes.push('The customer approved the design (they typed "approve" themselves), and it is recorded. Move to the next step now and tell them in one sentence what happens next.');
            } else {
              out.notes.push('The customer typed "approve", but there is nothing waiting for approval right now. Tell them where things stand in one sentence.');
            }
          }
        }
        out.notes = out.notes.filter(Boolean);
        return out;
      };
      const recorded = replyRoot && options.eventId ? replayOnce(replyRoot, 'reply', options.eventId, record) : record();
      const qualityNote = recorded.quality;
      if (!root) {
        const early = [secretNote, ...recorded.notes].filter(Boolean);
        return early.length ? done(0, hookContext('UserPromptSubmit', `[Piezas] ${early.join(' ')}`)) : done();
      }
      const state = loadState(root);
      const notes = [secretNote, ...recorded.notes].filter(Boolean);
      const reminder =
        `[Piezas] ${STEP_NAMES[state.phase]} (phase: ${state.phase}). ` +
        'Always: no local database; PIEZAS_API_KEY server-side only; no provider tokens in the app; plain language with the user.';
      const consent = qualityNote ? '' : qualityContextNote(root, state.phase);
      return done(0, hookContext('UserPromptSubmit', [reminder, ...notes, consent].filter(Boolean).join(' ')));
    }

    if (event === 'Stop') {
      // The AI's message that ends this turn: did it ask the owner to OK a
      // changed check, in Piezas's own words? Then the owner's next reply can
      // answer it by name; otherwise any earlier mark is cleared. In any
      // Piezas app, with or without the delivery protocol's state file (the
      // same folder the owner's replies are read in).
      const replyRoot = root ?? ownerReplyRoot(cwd);
      if (replyRoot) {
        try { markCheckChangeAsked(replyRoot, payload); } catch { /* best effort */ }
        // Did it relay a newer pause? Then that is what the owner has read.
        try { markPauseRelayed(replyRoot, payload); } catch { /* best effort */ }
      }
      if (!root) return done();
      // Did it show the owner the scan's result? Then a bare "accept" can refer to it.
      try { markQualityResultShown(root, payload); } catch { /* best effort */ }
      const continued = Boolean(payload.stop_hook_active);
      const state = loadState(root);
      if (state.phase === 'discover') return done();
      // Only the Hard No findings and the quality scan (once the owner turned
      // it on) hold a turn open. Ordinary build gaps (tests still to write,
      // config to finish) belong to the work, not to every reply — otherwise a
      // user's quick question turns into a forced fix-up.
      if (!continued) {
        const errors = newHardNoFindings(root);
        if (errors.length) {
          const lines = errors.slice(0, 8).map((f) => `- ${f.code} ${f.file ?? ''}: ${f.message}`);
          return done(
            0,
            JSON.stringify({
              decision: 'block',
              reason:
                `Piezas check found ${errors.length} problem(s) that would break the app or its rules. Fix them before finishing:\n${lines.join('\n')}`,
            }),
          );
        }
      }
      // The quality scan runs also when this stop follows an earlier hold: its
      // fix loop is bounded by its own round budget and hold count.
      const quality = qualityStop(root, payload, state.phase, {
        rulesDir: options.rulesDir,
        eventId: options.eventId,
        readOnly: options.readOnly,
        cli: options.cliPath ? `node "${options.cliPath}"` : 'npx piezas',
      });
      return quality ? done(0, JSON.stringify(quality)) : done();
    }
  } catch (error) {
    // PreToolUse fails closed: a check that cannot run must not let the step
    // through (exit 2 + reason blocks it in Claude Code and Codex).
    if (event === 'PreToolUse') return done(2, '', HOOK_FAILED_REASON);
    // The other events only add context (or hold a Stop / refuse a prompt
    // with a secret); there, a bug in our hook must not stop the user's
    // session, so they fail open with a note.
    return done(0, '', `piezas hook: ${error?.message || error}`);
  }
  return done();
}

// ===========================================================================
// Secrets never go through the chat
// ===========================================================================

export const SECRET_PATTERNS = [
  { what: 'a Piezas secret key', re: /\bsk_(?:live|test)_[A-Za-z0-9]{12,}/ },
  { what: 'a Piezas agent token', re: /\bagt_(?:live|test)_[A-Za-z0-9]{12,}/ },
  { what: 'an Anthropic API key', re: /\bsk-ant-[A-Za-z0-9_-]{20,}/ },
  { what: 'an OpenAI API key', re: /\bsk-(?:proj-|svcacct-)?[A-Za-z0-9_-]{32,}/ },
  { what: 'a Stripe secret key', re: /\b(?:rk|sk)_(?:live|test)_[A-Za-z0-9]{16,}/ },
  { what: 'an AWS access key', re: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/ },
  { what: 'a Google sign-in client secret', re: /\bGOCSPX-[A-Za-z0-9_-]{20,}/ },
  { what: 'a Microsoft sign-in client secret', re: /\b[A-Za-z0-9_.-]{3}\dQ~[A-Za-z0-9_.~-]{31,34}/ },
  { what: 'a GitHub token', re: /\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,})/ },
  { what: 'a Slack token', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/ },
  { what: 'a Google API key', re: /\bAIza[0-9A-Za-z_-]{35}\b/ },
  { what: 'a private key', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/ },
];
// NAME=value (or NAME: value) where the name says it is secret and the value
// looks like one: long, no spaces, letters and digits, not a placeholder.
export const SECRET_ASSIGNMENT = /\b((?:[A-Za-z][A-Za-z0-9_]*)?(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD|PWD))\s*[:=]\s*["']?([^\s"']{12,})/gi;

export function looksLikeSecretValue(name, value) {
  if (/PUBLISHABLE|PUBLIC_KEY$/i.test(name)) return false;
  if (/^pk_/.test(value)) return false;
  if (/^(?:your|my|example|placeholder|changeme|xxx|<|\$\{?|process\.env)/i.test(value) || /\.\.\.|x{4,}|\*{4,}/i.test(value)) return false;
  return /[A-Za-z]/.test(value) && /[0-9]/.test(value);
}

export function secretInPrompt(prompt) {
  const text = String(prompt || '');
  if (!text) return null;
  for (const { what, re } of SECRET_PATTERNS) {
    if (re.test(text)) return what;
  }
  for (const m of text.matchAll(SECRET_ASSIGNMENT)) {
    if (looksLikeSecretValue(m[1], m[2])) return `a value for ${m[1]}`;
  }
  return null;
}

export const SEND_ANYWAY = 'send anyway';

// isSendAnyway — the owner's own message starts with "send anyway": they read
// the warning and chose to share the value with their AI tool.
export function isSendAnyway(prompt) {
  return /^\s*["'“]?send anyway\b/i.test(String(prompt || ''));
}

export function secretBlockReason(what) {
  return `Piezas held this message back before your AI tool saw it: it looks like it contains ${what}. ` +
    'Chats can be kept for a long time, so anyone who later sees this chat could use it. Recommended: set it yourself ' +
    'instead, on the app page in the Piezas console (Hosting -> Environment), or in your own terminal with ' +
    '`npx piezas env set NAME=value`, then send your message again without the value. ' +
    `It's your choice: to send it to your AI tool anyway, send the message again starting with "${SEND_ANYWAY}". ` +
    'If it was a real key, consider replacing it later, since it was typed here.';
}

// secretSentNote — what the AI is told when the owner chose to send it.
export function secretSentNote(what) {
  return `The owner chose to share ${what} in this chat themselves (they started their message with "${SEND_ANYWAY}") ` +
    'after Piezas warned them. Use it only for what they asked. Never repeat the value back in your replies, and never put ' +
    'it in app code, a commit, a deploy or a command line; a local .env file is fine. If the live app needs it, tell them ' +
    'where they set it (the app page in the Piezas console, Hosting -> Environment). Suggest in one sentence replacing it ' +
    'later, since it is now in the chat.';
}

export function guardContent(options) {
  if (typeof options.content === 'string') return options.content;
  if (typeof options.contentFile === 'string' && options.contentFile && existsSync(options.contentFile)) {
    try {
      return readFileSync(options.contentFile, 'utf-8');
    } catch {
      return undefined;
    }
  }
  return undefined;
}

