export function kebabCase(flagKey) {
  return flagKey.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

export function usageError(message) {
  console.error(`  Error: ${message}`);
  console.error('  Run `npx piezas` for usage.');
  return 2;
}

export function lastValue(value) {
  return Array.isArray(value) ? value[value.length - 1] : value;
}

export function rejectUnknownFlags(flags, allowed, command) {
  for (const key of Object.keys(flags)) {
    if (!allowed.has(key)) {
      return usageError(`unknown flag --${kebabCase(key)} for ${command}`);
    }
  }
  return undefined;
}

